"""Compile captured pinned uTLS ClientHellos into the versioned Rust catalog."""
import json
from pathlib import Path
root = Path(__file__).resolve().parents[1] / 'crates/ztls/src'
manifest = json.loads((root/'fingerprint/presets/manifest.json').read_text())
def variant(name):
    family, version = name.split('-')
    return {'ios':'Ios','qq':'Qq','360':'Browser360'}.get(family, family.title()) + version.replace('.','')
variants = [variant(m['Name']) for m in manifest]
lines = ['// Generated by scripts/compile-clienthello-presets.py; do not edit.', 'use super::{ClientHelloProfile, Preset};', 'pub(super) fn preset(profile: ClientHelloProfile) -> Preset {', 'match profile {']
for m,v in zip(manifest,variants):
    lens=m['ECHLengths'] or [128]
    ciphers=m['ECHCiphers'] or [[1,1]]
    lines.append(f'ClientHelloProfile::{v} => Preset {{ wire: include_bytes!("presets/{m["Name"]}.bin"), padding: {str(m["Padding"]).lower()}, shuffle: {str(m["Shuffle"]).lower()}, ech_lengths: &{lens}, ech_ciphers: &{str([tuple(c) for c in ciphers])} }},')
lines += ['_ => unreachable!("resolve dynamic and legacy profiles before loading presets"),','}','}']
(root/'fingerprint/catalog.rs').write_text('\n'.join(lines)+'\n')
lines=['// Generated by scripts/compile-clienthello-presets.py; do not edit.', 'use std::{fmt, str::FromStr};','/// Pinned uTLS aa6edf4b11af82e110eea845bb2983d30138d651 profiles.', '#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]','pub enum ClientHelloProfile {']
lines += [v+',' for v in variants]+['/// Legacy Zero alias; the upstream never defined Edge 120.','Edge120,','Random,','Randomized,','RandomizedNoAlpn,','}']
lines += ['impl ClientHelloProfile {','pub const DEFAULT: Self = Self::Chrome133;', 'pub const VERSIONED: &\'static [Self] = &['+','.join('Self::'+v for v in variants)+'];','pub fn canonical_name(self) -> &\'static str { match self {']
lines += [f'Self::{v} => "{m["Name"]}",' for m,v in zip(manifest,variants)]
lines += ['Self::Edge120 => "edge-120", Self::Random => "random", Self::Randomized => "randomized", Self::RandomizedNoAlpn => "randomizednoalpn",','}}','pub fn alpn_protocols(self) -> &\'static [&\'static str] { if self == Self::RandomizedNoAlpn { &[] } else if matches!(self, Self::Firefox102) { &["h2"] } else { &["h2","http/1.1"] }}', '/// Negotiable TLS 1.3 suites; the wire preset also retains upstream legacy suites.', 'pub fn cipher_suites(self) -> &\'static [u16] { match self {', 'Self::Firefox63 | Self::Firefox65 | Self::Firefox99 | Self::Firefox102 | Self::Firefox105 | Self::Firefox120 | Self::Firefox148 => &[0x1301,0x1303,0x1302],','Self::Safari263 => &[0x1302,0x1303,0x1301],','_ => &[0x1301,0x1302,0x1303],','}}','}', 'impl Default for ClientHelloProfile { fn default() -> Self { Self::DEFAULT }}','impl fmt::Display for ClientHelloProfile { fn fmt(&self,f: &mut fmt::Formatter<\'_>) -> fmt::Result { f.write_str(self.canonical_name()) }}','impl FromStr for ClientHelloProfile { type Err = String; fn from_str(value: &str) -> Result<Self,String> {','let name = value.trim().to_ascii_lowercase();','let alias = match name.as_str() {','"chrome" | "hellochrome_auto" => Some(Self::Chrome133),','"firefox" | "hellofirefox_auto" => Some(Self::Firefox148),','"safari" | "hellosafari_auto" => Some(Self::Safari263),','"ios" | "helloios_auto" => Some(Self::Ios14),','"edge" | "helloedge_auto" => Some(Self::Edge85),','"qq" | "helloqq_auto" => Some(Self::Qq111),','"safari-16" => Some(Self::Safari160),','"edge-120" => Some(Self::Edge120),','"random" => Some(Self::Random),','"randomized" | "hellorandomized" | "hellorandomizedalpn" => Some(Self::Randomized),','"randomizednoalpn" | "randomized-no-alpn" | "hellorandomizednoalpn" => Some(Self::RandomizedNoAlpn),','_ => None }; if let Some(p) = alias { return Ok(p); }','let normalized = name.strip_prefix("hello").unwrap_or(&name).replace("_shuffle", "").replacen(\'_\', "-", 1).replace(\'_\', ".");','Self::VERSIONED.iter().copied().find(|p| p.canonical_name() == normalized).ok_or_else(|| format!("unsupported client fingerprint `{value}`; select a versioned TLS 1.3 browser preset, random, randomized or randomizednoalpn"))','}}', '#[cfg(feature = "runtime")]','mod catalog;','#[cfg(feature = "runtime")]','pub mod wire;','#[cfg(feature = "runtime")]','pub mod key_share;','#[cfg(feature = "runtime")]','struct Preset { wire: &\'static [u8], padding: bool, shuffle: bool, ech_lengths: &\'static [u16], ech_ciphers: &\'static [(u16,u16)] }']
modern = ['Firefox99', 'Firefox102', 'Firefox105', 'Firefox120', 'Chrome83', 'Chrome87', 'Chrome96', 'Chrome100', 'Chrome102', 'Chrome106', 'Chrome120', 'Chrome131', 'Ios13', 'Ios14', 'Edge85', 'Edge106', 'Safari160', 'Browser360110', 'Qq111']
lines += ["impl ClientHelloProfile {", "/// Exact Xray v26.3.27 ModernFingerprints random-selection set.", "pub const RANDOM_CANDIDATES: &'static [Self] = &[" + ','.join('Self::'+v for v in modern) + '];', '}']
(root/'fingerprint.rs').write_text('\n'.join(lines)+'\n#[cfg(feature = "runtime")]\nmod randomized;\n')
